const contact = {
  id:'contact',
  map:{
    src: <><iframe src='https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15282225.79979123!2d73.7250245393691!3d20.750301298393563!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x30635ff06b92b791%3A0xd78c4fa1854213a6!2sIndia!5e0!3m2!1sen!2sin!4v1587818542745!5m2!1sen!2sin' width='600' height='450' frameborder='0' style={{border:0}} allowfullscreen='false' aria-hidden='false' tabindex='0' title='map'></iframe></>
  },
  copy:{
    title: 'Contact Us',
    copy: <>We are based in Melbourne, Victoria, Australia.</>
  },
  email:{
    email:'info@oldmate.com.au',
    to:'emailto:info@oldmate.com.au'
  }
};

const Contact = () =>  (
    <section className='container-fluid p-0 pt-5 bg-charcoal' id={contact.id}>
      <div className='container justify-content-md-center py-5'>
      <div className='row px-4 g-0 flex-wrap-reverse'>
        <div className='col-lg-6'>
          <h2>{contact.copy.title}</h2>
          {contact.copy.copy}
          <br/>
          <a href={contact.email.to} className={contact.email.to}>{contact.email.email}</a>
        </div>
        <div className='col-lg-6 pb-3 text-center'>
          {contact.map.src}
        </div>
        </div>
      </div>
    </section>
)

export default Contact;
